package com.opentv.app.data;
import android.content.Context; import com.opentv.app.model.Channel; import java.io.*; import java.net.*; import java.nio.charset.StandardCharsets; import java.util.List;
public class PlaylistRepository {public static final long CACHE_MS=21600000L;private final Context context;public PlaylistRepository(Context c){context=c.getApplicationContext();}
public List<Channel> load(String url,boolean force)throws IOException{File f=new File(context.getCacheDir(),"playlist_"+Integer.toHexString(url.hashCode())+".m3u");String s;if(!force&&f.exists()&&System.currentTimeMillis()-f.lastModified()<CACHE_MS)s=read(f);else{s=download(url);try(FileOutputStream o=new FileOutputStream(f)){o.write(s.getBytes(StandardCharsets.UTF_8));}catch(IOException ignored){}}return M3uParser.parse(s);}
private String download(String src)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(src).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setInstanceFollowRedirects(true);c.setRequestProperty("User-Agent","OpenTV/1.1 AndroidTV");int code=c.getResponseCode();if(code<200||code>=300){c.disconnect();throw new IOException("HTTP "+code);}try(InputStream in=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)o.write(b,0,n);return o.toString("UTF-8");}finally{c.disconnect();}}
private static String read(File f)throws IOException{StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null)s.append(l).append('\n');}return s.toString();}}
